changeSet.sql:
CREATE TABLE maintenance_calibration (
  singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton),
  provider_id integer NOT NULL,
  token text NOT NULL,
  automatic boolean NOT NULL DEFAULT false,
  confirmed boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE maintenance_benchmark (
  singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton),
  job_id integer NOT NULL,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);

ALTER TABLE maintenance_calibration DROP CONSTRAINT maintenance_calibration_pkey;
ALTER TABLE maintenance_calibration ADD PRIMARY KEY (provider_id);
ALTER TABLE maintenance_calibration ADD UNIQUE (token);
ALTER TABLE maintenance_benchmark DROP CONSTRAINT maintenance_benchmark_pkey;
ALTER TABLE maintenance_benchmark ADD PRIMARY KEY (job_id);
ALTER TABLE maintenance_benchmark ADD COLUMN provider_id integer;
UPDATE maintenance_benchmark AS claim SET provider_id = (job.request_payload->>'provider_id')::integer
  FROM jobs AS job WHERE job.id = claim.job_id;
ALTER TABLE maintenance_benchmark ADD UNIQUE (provider_id);
